#pragma once
static void checkCompactRadicals(App& app,const std::string& dir){
    auto& s=app.s;auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("compact radical: "+why);};
    auto reset=[&](){s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.activateCommand("chooseSelectionTool_Marquee");s.refresh();};
    auto typed=[&](const char* value,Vec2 at){ObjectId text;s.doc.addText(at,10,"",&text);s.refresh();app.openText(text);app.textEditor.select(0,-1);auto input=W(value);SendMessageW(app.edit,EM_REPLACESEL,TRUE,LPARAM(input.c_str()));require(app.finishText(true)&&s.selected.size()==1&&s.selected[0].kind==ObjectKind::Atom,"real caption editor creates chemical atom");return s.selected[0].id;};
    for(int mode=0;mode<3;++mode){
        reset();auto sn=typed("bu3sn*",Vec2(30,60));ObjectId other;
        if(mode==0)other=typed("Bu3Sn·",Vec2(110,60));else{s.doc.addAtom(Vec2(115,60),6,&other);auto sem=s.doc.atoms().alive(other)->semantics;sem.radical=uint8_t(Radical::Doublet);sem.implicitHydrogens=3;s.doc.setAtomSemantics(other,sem);}
        std::vector<arrows::ArrowParams> arrows;for(auto id:{sn,other}){s.refresh();auto point=r62::arrows::mechanismRadicalPoints(s.doc,id).front();auto target=mode==1? r62::arrows::mechanismRadicalPoints(s.doc,id==sn?other:sn).front():Vec2(75,20);auto p=r62::arrows::resolvePreset(57,point,target,.6);p.mechanism=true;p.electronSource=ObjectRef(ObjectKind::Atom,id);if(mode==1)p.electronTarget=ObjectRef(ObjectKind::Atom,id==sn?other:sn);p.sourceVisualAnchor=4;app.chooseArrowPreset(57);auto count=s.doc.arrows().size();require(s.gesture(PointerPhase::Down,point).ok()&&s.gesture(PointerPhase::Move,target).ok()&&s.gesture(PointerPhase::Up,target).ok(),"draw hook from the actual typed radical dot");require(s.doc.arrows().size()==count+1,"hook created");bool read=false;require(r62::arrows::readArrow(s.doc,ObjectId(s.doc.arrows().size()-1),&p,&read).ok()&&read&&p.electronSource==ObjectRef(ObjectKind::Atom,id)&&p.sourceVisualAnchor==4,"hook captures the compact radical atom");arrows.push_back(p);}
        std::vector<mechanism::ElectronMove> moves;auto e=mechanism::inferElectronMoves(s.doc,arrows,&moves);require(e.ok(),"typed compact radicals infer coupling: "+e.message);auto before=s.doc.digest();s.selected=s.all();app.generateMechanismStep();require(s.doc.digest()!=before,"actual next-step button forms new bond");int unpaired=0;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)unpaired+=s.doc.atoms().alive(ref.id)->semantics.radical?1:0;require(!unpaired&&studio::analyze(s.doc,s.selected).valid,"coupled product consumes radicals and retains mass data");require(s.undo().ok()&&s.doc.digest()==before,"coupling undo preserves source text/radical");
        if(mode==0){s.refresh();s.fit();app.screenshot(dir+"/compact-radical-coupling.png");require(s.save(dir+"/compact-radicals.cdxml",true).ok(),"save compact radicals");Session reopened;require(reopened.open(dir+"/compact-radicals.cdxml").ok(),"reopen compact radicals");int count=0;for(const auto& a:reopened.doc.atoms().records())if(a.isAlive()&&a.element==50&&a.semantics.radical)++count;require(count==2,"compact radicals survive save and reopen");app.openText(kInvalidObjectId,sn);require(app.finishText(true)&&studioions::compact(s.doc,sn)&&s.doc.atoms().alive(sn)->semantics.radical==uint8_t(Radical::Doublet),"reopening the text editor preserves the chemical radical");s.refresh();s.activateCommand("chooseSelectionTool_Marquee");auto dot=r62::arrows::mechanismRadicalPoints(s.doc,sn).front();auto beforeDelete=s.doc.digest();require(app.beginElectronMarkerDrag(s.view().toDevice(dot)),"select compact radical dot");app.updateElectronMarkerDrag(s.view().toDevice(dot),true);require(app.deleteSelectedElectronMarker()&&s.doc.atomLabel(sn)=="Bu3SnH"&&!s.doc.atoms().alive(sn)->semantics.radical,"Delete removes the actual radical and restores one H");require(s.undo().ok()&&s.doc.digest()==beforeDelete,"radical deletion undo");}
    }
    reset();auto hydride=typed("Bu3SnH",Vec2(30,60));ObjectId h;require(exposeAttachedProton(s.doc,hydride,Vec2(65,60),&h).ok(),"expose Sn-H for abstraction");ObjectId donor;s.doc.addAtom(Vec2(90,100),6,&donor);auto sem=s.doc.atoms().alive(donor)->semantics;sem.implicitHydrogens=3;sem.radical=uint8_t(Radical::Doublet);s.doc.setAtomSemantics(donor,sem);auto bond=s.doc.bondBetween(hydride,h);
    std::vector<mechanism::ElectronMove> moves={{ObjectRef(ObjectKind::Bond,bond),ObjectRef(ObjectKind::Atom,hydride),1},{ObjectRef(ObjectKind::Bond,bond),ObjectRef(ObjectKind::Atom,h),1},{ObjectRef(ObjectKind::Atom,donor),ObjectRef(ObjectKind::Atom,h),1}};std::vector<ObjectRef> product;Document trial=s.doc;auto e=mechanism::generateNextStep(trial,moves,&product);require(e.ok(),"three fishhooks abstract H and regenerate tin radical: "+e.message);int radicals=0;for(auto ref:product)if(ref.kind==ObjectKind::Atom){const auto& a=*trial.atoms().alive(ref.id);if(a.semantics.radical){++radicals;require(a.element==50,"radical ends on tin");}}require(radicals==1&&studio::analyze(trial,product).valid,"abstraction conserves one radical and formula");
    reset();ObjectId text;s.doc.addText(Vec2(30,30),10,"Bu3Sn·",&text);s.refresh();require(s.save(dir+"/legacy-tin-caption.cdxml",true).ok(),"save legacy caption");Session reopened;require(reopened.open(dir+"/legacy-tin-caption.cdxml").ok()&&reopened.doc.stats().aliveTexts==0&&reopened.doc.stats().aliveAtoms==1,"old caption upgrades when reopened");
}
